  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "There is limited evidence in peer-reviewed literature on modelling for malaria optimization in limited resource settings. The country focus of the modelling studies included in the review were not representative of the burden of malaria in sub-Saharan Africa. ... The limited number of modelling analyses for malaria control optimization specific to countries within Africa and Asia is as a consequence of the lack or inaccessibility of country-specific epidemiologic and cost data at the national and subnational levels. This data gap limits future studies within the respective countries, limits the build-up of a critical mass of modellers within these countries, and makes it challenging for policymakers to make an evidence-based informed case to potential donors for future funding.",
      "reason": "The manuscript describes the current state of knowledge and highlights important uncertainties and data gaps (limited evidence, lack of country-specific data, representativeness issues)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "Models for malaria control optimization are used to disentangle the most efficient interventions or packages of interventions for inherently constrained budgets. This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "The abstract states the importance of modelling for decision-making under constrained budgets and explicitly explains the need and objectives of the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found describing existing similar systematic reviews or explaining the need for the current review as an update/replication; no prior review citations or discussion were provided in the retrieved evidence."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "This systematic review aimed to identify and characterise models for malaria control optimization for resource allocation in limited resource settings and assess their strengths and limitations.",
      "reason": "The review focuses on models for optimization of malaria control rather than on estimating effects of specific interventions; therefore describing mechanisms of action of interventions is not applicable to this review's primary aim."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": "text_10",
      "quote": "All studies investigated WHO-recommended interventions for control or elimination targets (Table 2), such as insecticide-treated nets [10, 11, 16-18, 25, 28, 29, 33-38], seasonal malaria chemoprevention [16, 18, 25, 28, 33, 37], intermittent preventive treatment [16, 25, 28, 37, 38], indoor residual spraying [16-18, 28, 29, 32-38], mass drug administration [16, 18, 29], and diagnosis and treatment through community health workers or health facilities [10, 11, 25, 28, 29, 32, 35-38].",
      "reason": "Although the review addresses multiple interventions and contexts (so a logic model could be applicable), no evidence was found that a logic model or similar hypothesised relationships between intervention components and outcomes was presented."
    }
